from __future__ import annotations

import os
from enum import Enum
from pathlib import Path
from typing import Any

import yaml
from pydantic import BaseModel, Field, field_validator, model_validator


class SegmentStatus(str, Enum):
    PENDING = "pending"
    CODING = "coding"
    PREFLIGHT = "preflight"
    SHIPPING = "shipping"
    VERIFYING = "verifying"
    REPAIRING = "repairing"
    EXPERIMENTING = "experimenting"
    SHIPPED = "shipped"
    FAILED = "failed"

    # Aliases for crash recovery detection
    @classmethod
    def active_states(cls) -> set[SegmentStatus]:
        return {cls.CODING, cls.PREFLIGHT, cls.SHIPPING, cls.VERIFYING, cls.REPAIRING, cls.EXPERIMENTING}


class BranchStrategy(str, Enum):
    DIRECT = "direct-to-main"
    PER_SEGMENT = "per-segment"
    PR = "pr"


class SegmentConfig(BaseModel):
    name: str
    status: SegmentStatus = SegmentStatus.PENDING
    prompt: str
    depends_on: list[str] = []
    commit: str | None = None
    deploy_url: str | None = None
    tag: str | None = None
    # TODO: touched_paths is reserved for future parallel execution (not yet implemented)
    touched_paths: list[str] = []


class BudgetConfig(BaseModel):
    max_usd_per_segment: float = 10.0
    max_usd_per_run: float = 50.0
    max_tokens_per_segment: int = 500_000
    halt_on_breach: bool = True
    optimization_budget_usd: float = 5.0
    model_pricing: dict[str, dict[str, float]] = {}


class RepairConfig(BaseModel):
    max_attempts: int = 3


class OptimizationConfig(BaseModel):
    enabled: bool = True
    max_experiments: int = 2
    min_repair_attempts: int = 1
    min_repair_diff_lines: int = 5
    budget_usd: float = 5.0


class MetaConfig(BaseModel):
    enabled: bool = True
    experiments: int = 3


class TimeoutsConfig(BaseModel):
    agent: int = 900
    deploy: int = 300
    preflight: int = 300


class ReflectionConfig(BaseModel):
    enabled: bool = True
    auto_run: bool = True
    history_depth: int = 10


class PreflightConfig(BaseModel):
    build: str | None = None
    lint: str | None = None
    test: str | None = None


class DeployConfig(BaseModel):
    provider: str = "vercel"
    routes: list[str] = ["/"]
    marker: str | None = None
    health_endpoint: str | None = None
    deploy_header: str | None = None
    script: str | None = None
    timeout: int = 300


AGENT_PRESETS: dict[str, str] = {
    "claude-code": "claude --print --permission-mode bypassPermissions",
    "codex": "codex --quiet",
    "aider": "aider --yes-always --no-git",
}


class ShipLoopConfig(BaseModel):
    project: str
    repo: str
    site: str
    platform: str = "vercel"
    branch_strategy: BranchStrategy = Field(default=BranchStrategy.PR, alias="branch")
    mode: str = "solo"
    agent: str | None = None
    agent_command: str = ""
    preflight: PreflightConfig = PreflightConfig()
    deploy: DeployConfig = Field(default_factory=DeployConfig)
    repair: RepairConfig = RepairConfig()
    meta: MetaConfig = MetaConfig()
    optimization: OptimizationConfig = OptimizationConfig()
    budget: BudgetConfig = BudgetConfig()
    timeouts: TimeoutsConfig = TimeoutsConfig()
    reflection: ReflectionConfig = ReflectionConfig()
    router: dict[str, str] = {}
    blocked_patterns: list[str] = []
    segments: list[SegmentConfig]

    model_config = {"populate_by_name": True}

    @field_validator("repo")
    @classmethod
    def resolve_repo_path(cls, v: str) -> str:
        expanded = Path(v).expanduser().resolve()
        return str(expanded)

    @model_validator(mode="before")
    @classmethod
    def migrate_verify_to_deploy(cls, data: dict[str, Any]) -> dict[str, Any]:
        if "verify" in data and "deploy" not in data:
            verify = data.pop("verify")
            data["deploy"] = verify
        if "branch" not in data and "branch_strategy" in data:
            data["branch"] = data.pop("branch_strategy")
        return data

    @model_validator(mode="after")
    def resolve_agent_preset(self) -> ShipLoopConfig:
        if self.agent_command:
            return self
        if self.agent and self.agent in AGENT_PRESETS:
            self.agent_command = AGENT_PRESETS[self.agent]
        elif self.agent:
            raise ValueError(
                f"Unknown agent preset '{self.agent}'. "
                f"Available: {', '.join(AGENT_PRESETS)}. "
                f"Or set agent_command directly."
            )
        if not self.agent_command:
            raise ValueError("Either 'agent' or 'agent_command' must be set")
        return self


def load_config(config_path: Path) -> ShipLoopConfig:
    if not config_path.exists():
        raise FileNotFoundError(f"Config not found: {config_path}")
    raw = yaml.safe_load(config_path.read_text())
    if not raw:
        raise ValueError(f"Empty config file: {config_path}")
    return ShipLoopConfig.model_validate(raw)


def save_config(config: ShipLoopConfig, config_path: Path) -> None:
    data = _config_to_serializable(config)
    content = yaml.dump(data, default_flow_style=False, sort_keys=False, allow_unicode=True)
    tmp_path = config_path.with_suffix(".yml.tmp")
    tmp_path.write_text(content)
    os.replace(str(tmp_path), str(config_path))


def _config_to_serializable(config: ShipLoopConfig) -> dict[str, Any]:
    data = config.model_dump(by_alias=True)
    data["branch"] = config.branch_strategy.value
    for seg in data.get("segments", []):
        seg["status"] = seg["status"].value if hasattr(seg["status"], "value") else seg["status"]
    # Drop None values for cleaner YAML
    return _strip_none(data)


def _strip_none(obj: Any) -> Any:
    if isinstance(obj, dict):
        return {k: _strip_none(v) for k, v in obj.items() if v is not None}
    if isinstance(obj, list):
        return [_strip_none(item) for item in obj]
    return obj

from __future__ import annotations

import importlib
import logging
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from .config import DeployConfig

from .providers.base import DeployVerifier, VerificationResult

logger = logging.getLogger("shiploop.deploy")

PROVIDER_MAP = {
    "vercel": "shiploop.providers.vercel",
    "netlify": "shiploop.providers.netlify",
    "custom": "shiploop.providers.custom",
}


def get_verifier(config: DeployConfig) -> DeployVerifier:
    provider = config.provider.lower()
    module_path = PROVIDER_MAP.get(provider)
    if not module_path:
        raise ValueError(f"Unknown deploy provider: {provider}. Available: {list(PROVIDER_MAP.keys())}")

    try:
        module = importlib.import_module(module_path)
        verifier_class = getattr(module, "Verifier")
        return verifier_class(config)
    except (ImportError, AttributeError) as e:
        raise ValueError(f"Failed to load provider '{provider}': {e}") from e


async def verify_deployment(
    config: DeployConfig,
    commit_hash: str,
    site_url: str,
) -> VerificationResult:
    verifier = get_verifier(config)
    return await verifier.verify(commit_hash, config, site_url)

from __future__ import annotations

import asyncio
import logging
import os
import time
from typing import TYPE_CHECKING

from .base import DeployVerifier, VerificationResult

if TYPE_CHECKING:
    from shiploop.config import DeployConfig

logger = logging.getLogger("shiploop.deploy.custom")

ALLOWED_ENV_KEYS = {"PATH", "HOME", "USER", "SHELL", "TERM"}


def _build_curated_env(commit_hash: str, site_url: str, extra_env: dict[str, str] | None = None) -> dict[str, str]:
    env: dict[str, str] = {}
    for key in ALLOWED_ENV_KEYS:
        if key in os.environ:
            env[key] = os.environ[key]
    env["SHIPLOOP_COMMIT"] = commit_hash
    env["SHIPLOOP_SITE"] = site_url
    if extra_env:
        env.update(extra_env)
    return env


class Verifier(DeployVerifier):
    async def verify(
        self,
        commit_hash: str,
        config: DeployConfig,
        site_url: str,
    ) -> VerificationResult:
        if not config.script:
            return VerificationResult(
                success=False,
                details="Custom provider requires 'script' field in deploy config",
            )

        start = time.monotonic()

        try:
            proc = await asyncio.create_subprocess_shell(
                config.script,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.STDOUT,
                env=_build_curated_env(commit_hash, site_url),
            )
            stdout, _ = await asyncio.wait_for(proc.communicate(), timeout=config.timeout)
            output = stdout.decode(errors="replace").strip()
            elapsed = time.monotonic() - start

            if proc.returncode == 0:
                return VerificationResult(
                    success=True,
                    deploy_url=site_url,
                    details=output[:500],
                    duration_seconds=elapsed,
                )
            return VerificationResult(
                success=False,
                details=f"Script exited {proc.returncode}: {output[:500]}",
                duration_seconds=elapsed,
            )

        except asyncio.TimeoutError:
            return VerificationResult(
                success=False,
                details=f"Custom verify script timed out after {config.timeout}s",
                duration_seconds=time.monotonic() - start,
            )

from __future__ import annotations

import asyncio
import logging
import time
from typing import TYPE_CHECKING
from urllib.request import Request, urlopen
from urllib.error import URLError

from .base import DeployVerifier, VerificationResult

if TYPE_CHECKING:
    from shiploop.config import DeployConfig

logger = logging.getLogger("shiploop.deploy.netlify")

POLL_INTERVAL = 10


class Verifier(DeployVerifier):
    async def verify(
        self,
        commit_hash: str,
        config: DeployConfig,
        site_url: str,
    ) -> VerificationResult:
        start = time.monotonic()
        timeout = config.timeout
        deadline = start + timeout
        last_error = ""

        while time.monotonic() < deadline:
            for route in config.routes:
                url = site_url.rstrip("/") + route
                try:
                    result = await asyncio.to_thread(self._check_url, url, config.marker)
                    if result.success:
                        result.duration_seconds = time.monotonic() - start
                        return result
                    last_error = result.details
                except Exception as e:
                    last_error = str(e)

            await asyncio.sleep(POLL_INTERVAL)

        return VerificationResult(
            success=False,
            details=f"Timed out after {timeout}s. Last error: {last_error}",
            duration_seconds=time.monotonic() - start,
        )

    def _check_url(self, url: str, marker: str | None) -> VerificationResult:
        req = Request(url, method="GET")
        req.add_header("User-Agent", "shiploop/4.0.0")

        try:
            with urlopen(req, timeout=15) as resp:
                status = resp.status
                headers = {k.lower(): v for k, v in resp.getheaders()}
                body = resp.read(8192).decode(errors="replace")
        except URLError as e:
            return VerificationResult(success=False, details=f"Request failed: {e}")

        if status != 200:
            return VerificationResult(success=False, details=f"HTTP {status} for {url}")

        deploy_url = headers.get("x-nf-request-id")

        if marker and marker not in body:
            return VerificationResult(
                success=False,
                details=f"Marker '{marker}' not found in response body",
            )

        return VerificationResult(
            success=True,
            deploy_url=deploy_url or url,
            details="HTTP 200 OK",
        )

