class Verifier(DeployVerifier):
    async def verify(
        self,
        commit_hash: str,
        config: DeployConfig,
        site_url: str,
    ) -> VerificationResult:
        start = time.monotonic()
        timeout = config.timeout
        deploy_header = config.deploy_header or "x-vercel-deployment-url"

        deadline = start + timeout
        last_error = ""

        while time.monotonic() < deadline:
            for route in config.routes:
                url = site_url.rstrip("/") + route
                try:
                    result = await asyncio.to_thread(self._check_url, url, deploy_header, config.marker)
                    if result.success:
                        result.duration_seconds = time.monotonic() - start
                        return result
                    last_error = result.details
                except Exception as e:
                    last_error = str(e)

            await asyncio.sleep(POLL_INTERVAL)

        return VerificationResult(
            success=False,
            details=f"Timed out after {timeout}s. Last error: {last_error}",
            duration_seconds=time.monotonic() - start,
        )

    def _check_url(self, url: str, deploy_header: str, marker: str | None) -> VerificationResult:
        req = Request(url, method="GET")
        req.add_header("User-Agent", "shiploop/4.0.0")

        try:
            with urlopen(req, timeout=15) as resp:
                status = resp.status
                headers = {k.lower(): v for k, v in resp.getheaders()}
                body = resp.read(8192).decode(errors="replace")
        except URLError as e:
            return VerificationResult(success=False, details=f"Request failed: {e}")

        if status != 200:
            return VerificationResult(success=False, details=f"HTTP {status} for {url}")

        deploy_url = headers.get(deploy_header.lower())

        if marker and marker not in body:
            return VerificationResult(
                success=False,
                deploy_url=deploy_url,
                details=f"Marker '{marker}' not found in response body",
            )

        return VerificationResult(
            success=True,
            deploy_url=deploy_url or url,
            details=f"HTTP 200 OK",
        )

from __future__ import annotations

import json
import sys
import time
from dataclasses import dataclass, field
from typing import TextIO

from .config import SegmentConfig, SegmentStatus, ShipLoopConfig


@dataclass
class SegmentReport:
    name: str
    status: str
    commit: str | None = None
    tag: str | None = None
    deploy_url: str | None = None
    duration_seconds: float = 0.0
    cost_usd: float = 0.0
    repair_attempts: int = 0
    meta_experiments: int = 0
    errors: list[str] = field(default_factory=list)


class Reporter:
    def __init__(self, config: ShipLoopConfig, out: TextIO | None = None):
        self.config = config
        self.out = out or sys.stdout
        self.segment_reports: list[SegmentReport] = []
        self._start_time = time.monotonic()
        self._segment_start: float | None = None

    def pipeline_start(self) -> None:
        total = len(self.config.segments)
        self._print(f"\n🚢 Ship Loop: {self.config.project} ({total} segments)")
        self._print("━" * 50)

    def segment_start(self, index: int, segment: SegmentConfig) -> None:
        total = len(self.config.segments)
        self._segment_start = time.monotonic()
        self._print(f"\n🔄 Segment {index + 1}/{total}: {segment.name}")

    def segment_phase(self, segment_name: str, phase: str) -> None:
        elapsed = self._elapsed_segment()
        self._print(f"   {_phase_emoji(phase)} {phase}... ({elapsed})")

    def segment_shipped(self, index: int, report: SegmentReport) -> None:
        total = len(self.config.segments)
        cost_str = f", ${report.cost_usd:.2f}" if report.cost_usd > 0 else ""
        short_sha = (report.commit or "")[:7]
        elapsed = _format_duration(report.duration_seconds)
        self._print(
            f"✅ Segment {index + 1}/{total}: {report.name} — shipped "
            f"({short_sha}) [{elapsed}{cost_str}]"
        )
        self.segment_reports.append(report)

    def segment_failed(self, index: int, report: SegmentReport) -> None:
        total = len(self.config.segments)
        self._print(f"❌ Segment {index + 1}/{total}: {report.name} — FAILED")
        if report.repair_attempts > 0:
            self._print(f"   Repair: {report.repair_attempts} attempts failed")
        if report.meta_experiments > 0:
            self._print(f"   Meta: {report.meta_experiments} experiments failed")
        for error in report.errors[-3:]:
            self._print(f"   {error}")
        self.segment_reports.append(report)

    def repair_attempt(self, segment_name: str, attempt: int, max_attempts: int) -> None:
        self._print(f"   🔧 Repair attempt {attempt}/{max_attempts}")

    def repair_success(self, segment_name: str, attempt: int) -> None:
        self._print(f"   ✅ Preflight passed after repair attempt {attempt}")

    def repair_failure(self, segment_name: str, attempt: int, error_summary: str) -> None:
        self._print(f"   ❌ Repair {attempt} failed: {error_summary[:100]}")

    def meta_start(self) -> None:
        self._print("   🧪 Entering meta loop...")

    def meta_analysis(self) -> None:
        self._print("   🧠 Running meta-analysis...")

    def experiment_start(self, exp_num: int, total: int) -> None:
        self._print(f"   🧪 Experiment {exp_num}/{total}")

    def experiment_result(self, exp_num: int, passed: bool, diff_lines: int = 0) -> None:
        if passed:
            self._print(f"   ✅ Experiment {exp_num} passed (diff: {diff_lines} lines)")
        else:
            self._print(f"   ❌ Experiment {exp_num} failed")

    def experiment_winner(self, exp_num: int, branch: str) -> None:
        self._print(f"   🏆 Winner: experiment {exp_num} (branch: {branch})")

    def optimization_start(self, segment_name: str) -> None:
        self._print(f"   🔬 Background optimization for '{segment_name}'...")

    def optimization_result(self, segment_name: str, result: dict) -> None:
        if result.get("winner") is not None:
            self._print(f"   🎯 Optimization found: {result.get('improvement_type', '')} for '{segment_name}'")
        else:
            self._print(f"   ℹ️  No optimization found for '{segment_name}'")

    def optimization_skipped(self, segment_name: str, reason: str) -> None:
        self._print(f"   ⏭️  Optimization skipped for '{segment_name}': {reason}")

    def budget_warning(self, segment: str, cost: float, limit: float) -> None:
        self._print(f"⚠️  Budget alert: {segment} at ${cost:.2f} / ${limit:.2f}")

    def budget_halt(self, segment: str, cost: float, limit: float) -> None:
        self._print(f"🛑 Budget exceeded: {segment} at ${cost:.2f} (limit: ${limit:.2f}) — halting")

    def pipeline_complete(self) -> None:
        elapsed = time.monotonic() - self._start_time
        shipped = sum(1 for r in self.segment_reports if r.status == "shipped")
        total = len(self.config.segments)
        total_cost = sum(r.cost_usd for r in self.segment_reports)

        self._print("\n" + "━" * 50)
        if shipped == total:
            self._print(f"🏁 Ship loop complete! {shipped}/{total} segments shipped.")
        else:
            failed = total - shipped
            self._print(f"🏁 Ship loop finished. {shipped}/{total} shipped, {failed} failed.")
        self._print(f"   Total time: {_format_duration(elapsed)}")
        if total_cost > 0:
            self._print(f"   Total cost: ${total_cost:.2f}")
        self._print("━" * 50)

    def get_json_report(self) -> str:
        return json.dumps(
            {
                "project": self.config.project,
                "total_segments": len(self.config.segments),
                "shipped": sum(1 for r in self.segment_reports if r.status == "shipped"),
                "failed": sum(1 for r in self.segment_reports if r.status == "failed"),
                "total_cost_usd": sum(r.cost_usd for r in self.segment_reports),
                "total_duration_seconds": time.monotonic() - self._start_time,
                "segments": [
                    {
                        "name": r.name,
                        "status": r.status,
                        "commit": r.commit,
                        "tag": r.tag,
                        "cost_usd": r.cost_usd,
                        "duration_seconds": r.duration_seconds,
                        "repair_attempts": r.repair_attempts,
                    }
                    for r in self.segment_reports
                ],
            },
            indent=2,
        )

    def _elapsed_segment(self) -> str:
        if self._segment_start is None:
            return ""
        return _format_duration(time.monotonic() - self._segment_start)

    def _print(self, msg: str) -> None:
        print(msg, file=self.out, flush=True)


def _phase_emoji(phase: str) -> str:
    return {
        "coding": "🤖",
        "preflight": "🛫",
        "shipping": "📦",
        "verifying": "🔍",
        "repairing": "🔧",
        "experimenting": "🧪",
    }.get(phase, "▶")


def _format_duration(seconds: float) -> str:
    if seconds < 60:
        return f"{seconds:.0f}s"
    minutes = int(seconds // 60)
    secs = int(seconds % 60)
    return f"{minutes}m {secs}s"

import json
import tempfile
from pathlib import Path

import pytest

from shiploop.budget import BudgetConfig, BudgetTracker, UsageRecord, estimate_cost, estimate_from_prompt, parse_token_usage


@pytest.fixture
def budget_dir():
    with tempfile.TemporaryDirectory() as d:
        yield Path(d)


@pytest.fixture
def tracker(budget_dir):
    config = BudgetConfig(
        max_usd_per_segment=10.0,
        max_usd_per_run=50.0,
        halt_on_breach=True,
    )
    return BudgetTracker(config, budget_dir)


class TestBudgetTracker:
    def test_record_and_retrieve(self, tracker):
        record = UsageRecord(
            segment="dark-mode",
            loop="ship",
            tokens_in=1000,
            tokens_out=500,
            estimated_cost_usd=0.05,
            duration_seconds=10.0,
        )
        tracker.record_usage(record)

        assert tracker.get_segment_cost("dark-mode") == 0.05
        assert tracker.get_run_cost() == 0.05

    def test_budget_check_within_limits(self, tracker):
        assert tracker.check_budget("dark-mode") is True

    def test_budget_check_segment_exceeded(self, tracker):
        for i in range(5):
            tracker.record_usage(UsageRecord(
                segment="dark-mode", loop=f"repair-{i}",
                estimated_cost_usd=3.0,
            ))

        assert tracker.check_budget("dark-mode") is False

    def test_budget_check_run_exceeded(self, tracker):
        for i in range(6):
            tracker.record_usage(UsageRecord(
                segment=f"seg-{i}", loop="ship",
                estimated_cost_usd=9.0,
            ))

        assert tracker.check_budget("new-seg") is False

    def test_budget_check_halt_disabled(self, budget_dir):
        config = BudgetConfig(halt_on_breach=False)
        t = BudgetTracker(config, budget_dir)
        for i in range(10):
            t.record_usage(UsageRecord(
                segment="s", loop="ship", estimated_cost_usd=100.0,
            ))
        assert t.check_budget("s") is True

    def test_persistence(self, budget_dir):
        config = BudgetConfig()
        t1 = BudgetTracker(config, budget_dir)
        t1.record_usage(UsageRecord(
            segment="test", loop="ship", estimated_cost_usd=1.23,
        ))

        t2 = BudgetTracker(config, budget_dir)
        assert t2.get_run_cost() == 1.23

    def test_summary(self, tracker):
        tracker.record_usage(UsageRecord(
            segment="seg-1", loop="ship", estimated_cost_usd=2.0,
        ))
        tracker.record_usage(UsageRecord(
            segment="seg-2", loop="ship", estimated_cost_usd=3.0,
        ))
        summary = tracker.get_summary()
        assert summary["total_cost_usd"] == 5.0
        assert summary["by_segment"]["seg-1"] == 2.0
        assert summary["by_segment"]["seg-2"] == 3.0


class TestTokenParsing:
    def test_parse_token_usage(self):
        output = """
        Some output here
        input_tokens: 1,234
        output_tokens: 567
        Done.
        """
        tokens_in, tokens_out = parse_token_usage(output)
        assert tokens_in == 1234
        assert tokens_out == 567

    def test_parse_no_tokens(self):
        tokens_in, tokens_out = parse_token_usage("hello world")
        assert tokens_in == 0
        assert tokens_out == 0

    def test_parse_claude_format(self):
        output = "input tokens: 12345\noutput tokens: 6789"
        tokens_in, tokens_out = parse_token_usage(output)
        assert tokens_in == 12345
        assert tokens_out == 6789

    def test_parse_gpt_format_with_equals(self):
        output = "input_tokens=1000\noutput_tokens=500"
        tokens_in, tokens_out = parse_token_usage(output)
        assert tokens_in == 1000
        assert tokens_out == 500

    def test_parse_large_numbers_with_commas(self):
        output = "input_tokens: 1,234,567\noutput_tokens: 890,123"
        tokens_in, tokens_out = parse_token_usage(output)
        assert tokens_in == 1234567
        assert tokens_out == 890123

    def test_parse_empty_string(self):
        tokens_in, tokens_out = parse_token_usage("")
        assert tokens_in == 0
        assert tokens_out == 0


class TestEstimateFromPrompt:
    def test_basic_estimation(self):
        tokens_in, tokens_out = estimate_from_prompt(4000, 10.0)
        assert tokens_in == 1000
        assert tokens_out == 300

    def test_minimum_floor_input(self):
        tokens_in, tokens_out = estimate_from_prompt(0, 10.0)
        assert tokens_in == 100

    def test_minimum_floor_output(self):
        tokens_in, tokens_out = estimate_from_prompt(4000, 0.0)
        assert tokens_out == 200

    def test_long_duration_scales_output(self):
        tokens_in, tokens_out = estimate_from_prompt(4000, 60.0)
        assert tokens_out == 1800


class TestCostEstimate:
    def test_default_pricing(self):
        cost = estimate_cost(1_000_000, 100_000)
        assert cost > 0

    def test_zero_tokens(self):
        cost = estimate_cost(0, 0)
        assert cost == 0.0

    def test_specific_model(self):
        cost = estimate_cost(1_000_000, 1_000_000, "claude-opus-4-6")
        assert cost > estimate_cost(1_000_000, 1_000_000, "claude-haiku-4-5")
